 on('family','change',e=>{state.kind=e.target.value;state.weight=state.kind==='E8'?2:state.target;render();});
 on('target','change',e=>{state.target=Number(e.target.value);state.rank=2**(state.target-1)-1;state.weight=state.target;render();});
 on('weight','input',e=>{state.weight=Number(e.target.value);$('weight-value').textContent=state.weight.toFixed(2);result();draw();});
