function text(x,y,value,cl='',anchor='start',extra=''){return `<text x="${f(x)}" y="${f(y)}" class="${cl}" text-anchor="${anchor}" ${extra}>${esc(value)}</text>`;}
function path(points,color,width=1,opacity=1,extra=''){return `<path d="${points.map(([x,y],i)=>`${i?'L':'M'}${f(x)},${f(y)}`).join(' ')}" fill="none" stroke="${color}" stroke-width="${width}" opacity="${opacity}" ${extra}/>`;}
function e8Plot(w,h){const cx=w/2,cy=h/2+2,r=Math.min(w-72,h-90)/2/Math.max(...data.roots.map(p=>Math.hypot(p.x,p.y,p.z*state.depth))),sy=Math.sin(state.yaw),co=Math.cos(state.yaw),sp=Math.sin(state.pitch),cp=Math.cos(state.pitch);screenPoints=data.roots.map(p=>{const xx=p.x*co+p.z*state.depth*sy,zz=-p.x*sy+p.z*state.depth*co,yy=p.y*cp-zz*sp,z=p.y*sp+zz*cp;return {x:cx+xx*r,y:cy+yy*r,z,id:p.id};});let out=line(cx-r-12,cy,cx+r+12,cy,C.line,1,.55)+line(cx,cy-r-12,cx,cy+r+12,C.line,1,.55);const selected=data.roots[state.selected],p=screenPoints[state.selected];
 for(let o=0;o<8;o++){const pts=screenPoints.slice(o*30,o*30+30).map(p=>[p.x,p.y]);pts.push(pts[0]);out+=path(pts,o===selected.orbit?C.gold:C.cyan,o===selected.orbit?1.1:.6,o===selected.orbit?.48:.12);}
