 out+=text(16,24,'240 ROOTS / 8 ORBITS','plot-label')+text(w-16,w<430?44:24,state.depth?'PLANE + EXPONENT 7':'COXETER PLANE','plot-label','end');
 out+=text(w/2,h-13,w<500?'30 Coxeter steps return to the start.':`Selected: orbit ${selected.orbit+1}, step ${selected.step+1} · 30 steps return to the same root`,'','middle');return out;
