function axes(w,h,values,xDomain,yDomain,xLabel,yLabel){const left=66,right=22,top=65,bottom=60,plotW=w-left-right,plotH=h-top-bottom,x=v=>left+(v-xDomain[0])/(xDomain[1]-xDomain[0])*plotW,y=v=>top+(yDomain[1]-v)/(yDomain[1]-yDomain[0])*plotH,tick=v=>Math.abs(v)<1e-10?'0':Math.abs(v)<.001||Math.abs(v)>9999?v.toExponential(1):Number(v.toPrecision(3)).toString();let out='';for(let k=0;k<=4;k++){const v=yDomain[0]+(yDomain[1]-yDomain[0])*k/4,yy=y(v);out+=line(left,yy,w-right,yy,C.line,1,.7)+text(left-10,yy+4,tick(v),'','end');}for(let k=0;k<=3;k++){const v=xDomain[0]+(xDomain[1]-xDomain[0])*k/3,xx=x(v);out+=text(xx,h-bottom+25,(xLabel==='Term index n'?Math.round(v):Number(v.toFixed(2))).toString(),'','middle');}out+=line(left,top,left,h-bottom)+line(left,h-bottom,w-right,h-bottom)+text((left+w-right)/2,h-10,xLabel,'axis-title','middle')+text(left,28,yLabel,'axis-title');return {out,x,y,left,right,top,bottom,plotH,plotW};}
function raghavaPlot(w,h){const rows=M.convergence(state.j,state.denominator,24),min=Math.min(...rows.map(x=>x.logRatio)),bottom=Math.min(-10,Math.floor(min/10)*10),a=axes(w,h,rows,[state.j,24],[bottom,0],'Term index n','log₁₀(term / exact sum)');let out=a.out;const pts=rows.map(p=>[a.x(p.n),a.y(p.logRatio)]);out+=path(pts,C.cyan,2);for(const p of pts)out+=circle(p[0],p[1],3.3,C.cyan);out+=text(a.left,48,`θ = π/${state.denominator.toLocaleString()} · j = ${state.j}`,'plot-label');return out;}
function mellinPlot(w,h){const density=state.view==='density',samples=Array.from({length:401},(_,i)=>{const x=density?.008+i*(10-.008)/400:1.25+i*4.75/400;if(density)return {x,y:M.density(state.kind,state.rank,state.weight,x)};const z=M.factors(state.kind,state.rank,x);return {x,y:Math.log2(z.roots/-z.cartan)};});let low=Math.min(0,...samples.map(p=>p.y)),high=Math.max(0,...samples.map(p=>p.y));const pad=(high-low)*.08||1;low-=pad;high+=pad;const a=axes(w,h,samples,density?[0,10]:[1.25,6],[low,high],density?'Log coordinate t = −log x':'Integral weight s',density?'Signed density tˢ⁻¹ e⁻ᵗ K(e⁻ᵗ)':'log₂(root term / |Cartan term|)');let out=a.out,base=a.y(0),points=samples.map(p=>[a.x(p.x),a.y(p.y)]);out+=line(a.left,base,w-a.right,base,C.muted,1,.8);out+=`<defs><clipPath id="positive-area"><rect x="${a.left}" y="${a.top}" width="${a.plotW}" height="${Math.max(0,base-a.top)}"/></clipPath><clipPath id="negative-area"><rect x="${a.left}" y="${base}" width="${a.plotW}" height="${Math.max(0,h-a.bottom-base)}"/></clipPath></defs>`;
 const fill=`M${f(points[0][0])},${f(base)} `+points.map(p=>`L${f(p[0])},${f(p[1])}`).join(' ')+` L${f(points[points.length-1][0])},${f(base)} Z`;
 out+=`<path d="${fill}" fill="${C.cyan}" opacity=".09" clip-path="url(#positive-area)"/><path d="${fill}" fill="${C.coral}" opacity=".12" clip-path="url(#negative-area)"/>`+path(points,C.cyan,2,1,'clip-path="url(#positive-area)"')+path(points,C.coral,2,1,'clip-path="url(#negative-area)"');
 const nearestGrid=Math.min(...Array.from({length:5},(_,k)=>Math.abs(a.y(low+(high-low)*k/4)-base)));if(nearestGrid>15)out+=text(a.left-10,base+4,'0','','end');
