function draw(){if(!data)return;const stage=$('visual-stage'),w=Math.max(240,stage.clientWidth),h=stage.clientHeight;let content=state.chapter==='e8'?e8Plot(w,h):state.chapter==='phase'?phasePlot(w,h):state.chapter==='raghava'?raghavaPlot(w,h):mellinPlot(w,h);const svg=$('atlas-plot');svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML=`<title id="plot-title">${esc(descriptions[state.chapter].visual)}</title><desc id="plot-description">${esc(descriptions[state.chapter].description+' '+$('visual-caption').textContent)}</desc>`+content;}
